<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free URL Query Parser','description'=>'Parse a URL and view its protocol, host, path and query parameters.','url'=>'https://smarttoolz.in/tools/url-query-parser/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>URL Query Parser</h1><p>Inspect URL components and query parameters.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="i" placeholder="https://example.com/page?a=1&b=2"><button id="go" class="tool-btn">Parse URL</button><pre id="o"></pre></div></section></main><script>go.onclick=()=>{try{let u=new URL(i.value);let q=Object.fromEntries(u.searchParams.entries());o.textContent=JSON.stringify({protocol:u.protocol,host:u.host,path:u.pathname,query:q},null,2)}catch(e){o.textContent='Invalid URL.'}}</script><?php smarttoolz_tool_page_end(); ?>